import{_ as s}from"./chunks/panel-dashboard.Ddd5T6mA.js";import{_ as a}from"./chunks/panel-http-rule-form.BRe8ZX4N.js";import{_ as e,o as i,c as n,a2 as r}from"./chunks/framework.CuEaBji2.js";const l="/nginx-reverse-emby/screenshots/panel-login.png",y=JSON.parse('{"title":"快速开始：跑通第一条反代","description":"在 Linux VPS 上部署 NRE，创建第一条 HTTP/HTTPS 反向代理规则，并检查后端与入口连通性。","frontmatter":{"description":"在 Linux VPS 上部署 NRE，创建第一条 HTTP/HTTPS 反向代理规则，并检查后端与入口连通性。"},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md","lastUpdated":1792150187000}'),p={name:"getting-started/quickstart.md"};function d(h,t,o,c,k,g){return i(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="快速开始-跑通第一条反代" tabindex="-1">快速开始：跑通第一条反代 <a class="header-anchor" href="#快速开始-跑通第一条反代" aria-label="Permalink to &quot;快速开始：跑通第一条反代&quot;">​</a></h1><p>目标是让浏览器通过你的域名打开后端服务。单机使用只需要内置的 <code>local</code> 节点；先完成这一条链路，再配置多节点、Relay 或插件。</p><p>如果主要用来播放媒体，可以配合 <a href="./../guides/emby-jellyfin">Emby / Jellyfin 反代指南</a> 验证登录、播放和拖动进度。</p><h2 id="准备三个东西" tabindex="-1">准备三个东西 <a class="header-anchor" href="#准备三个东西" aria-label="Permalink to &quot;准备三个东西&quot;">​</a></h2><table tabindex="0"><thead><tr><th>准备项</th><th>示例与要求</th></tr></thead><tbody><tr><td>Linux VPS</td><td>可运行 Docker，能够访问后端；安装脚本可按需安装 Docker / Compose</td></tr><tr><td>业务入口域名</td><td><code>app.example.com</code>，DNS 指向 VPS；放行 TCP 80 / 443，确认没有其它服务占用</td></tr><tr><td>后端地址</td><td><code>https://origin.example.net</code> 或 VPS <strong>确实能访问到的</strong> <code>http://192.168.1.100:8096</code></td></tr></tbody></table><p>家里的 <code>192.168.x.x</code> 地址通常不能从公网 VPS 直接访问。需要先打通网络，或按 <a href="./../guides/relay">Relay 指南</a> 接入内网节点。</p><p>在 VPS 上先检查后端：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --connect-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-time</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://origin.example.net</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>收到 HTTP 响应后再继续。<code>401/403</code> 表示服务限制访问；<code>405</code> 可能只是服务不支持 HEAD，需用浏览器验证。解析失败、连接失败或超时则先排查后端网络。</p><h2 id="第一步-部署并登录" tabindex="-1">第一步：部署并登录 <a class="header-anchor" href="#第一步-部署并登录" aria-label="Permalink to &quot;第一步：部署并登录&quot;">​</a></h2><p>在 VPS 上执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/sakullla/nginx-reverse-emby/main/scripts/deploy-compose.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>脚本会创建目录、生成随机 token 并启动服务。提示填写的域名是 <strong>面板域名</strong>（例如 <code>panel.example.com</code>），业务入口域名在下一步添加，两者请使用不同域名。</p><ul><li>有面板域名：先将 DNS 指向 VPS，填入域名；Cloudflare Token 可选，跳过时使用 HTTP-01 验证。</li><li>暂时没有面板域名：可回车跳过，按脚本输出的临时访问方式登录，之后再为面板配置 HTTPS。</li></ul><p>保存脚本输出的 <strong>访问地址</strong> 和 <strong>Panel token</strong>。打开该地址，用 Panel token 登录；全新部署不需要用户名和密码。临时 HTTP 不加密令牌，公网长期使用前请启用 HTTPS。</p><p><img src="'+l+'" alt="登录面板"></p><p><img src="'+s+'" alt="仪表盘首页"></p><p>需要自行维护 Compose 或已有外部反代？使用 <a href="./deploy">部署指南</a>。手动部署默认只监听 <code>127.0.0.1:8080</code>，需要通过 SSH 隧道首次访问。</p><h2 id="第二步-创建第一条规则" tabindex="-1">第二步：创建第一条规则 <a class="header-anchor" href="#第二步-创建第一条规则" aria-label="Permalink to &quot;第二步：创建第一条规则&quot;">​</a></h2><p>进入 <strong>流量管理 → HTTP 规则</strong>，节点选择 <code>local</code>，点击 <strong>添加规则</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>入口域名</td><td>选择 <code>https://</code>，填写 <code>app.example.com</code></td></tr><tr><td>后端地址</td><td><code>https://origin.example.net</code>，填写真实协议与端口</td></tr><tr><td>启用规则</td><td>开启</td></tr><tr><td>其它设置</td><td>先保留默认值</td></tr></tbody></table><p><img src="'+a+`" alt="添加 HTTP 规则"></p><p>点击 <strong>创建规则</strong>。<code>local</code> 节点同步配置后，自动申请 HTTPS 证书。默认 HTTP-01 要求域名解析正确且外部能访问 TCP 80；访问 HTTPS 还需要 TCP 443。证书未就绪时到 <strong>基础设施 → 证书管理</strong> 查看状态。</p><p>如果暂时无法完成证书验证，可以先用 <code>http://</code> 验证页面连通性，确认后改为 HTTPS；不要通过未加密的公网入口提交账号密码。80 端口不可用、需要通配符或 DNS-01 时，见 <a href="./../guides/certificates">证书与 HTTPS</a>。</p><h2 id="第三步-从客户端验证" tabindex="-1">第三步：从客户端验证 <a class="header-anchor" href="#第三步-从客户端验证" aria-label="Permalink to &quot;第三步：从客户端验证&quot;">​</a></h2><p>在你实际使用的电脑或手机上打开 <code>https://app.example.com</code>：</p><ul><li>页面显示的是预期的后端服务。</li><li>浏览器证书有效，登录和主要功能正常。</li><li>媒体服务再验证播放与拖动进度，见 <a href="./../guides/emby-jellyfin#验证是否真正可用">媒体反代验收</a>。</li></ul><p><strong>打不开时</strong>，在运行规则的 VPS 上执行只读检查：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/sakullla/nginx-reverse-emby/main/scripts/check-proxy.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-proxy.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-proxy.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://origin.example.net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>请把示例换成自己的服务首页地址，<strong>不要带 token、用户名密码或带签名的播放链接</strong>。工具只发送 HEAD，不修改配置，也不下载视频。</p><table tabindex="0"><thead><tr><th>检查结果</th><th>下一步</th></tr></thead><tbody><tr><td>后端 DNS / 连接失败</td><td>先解决 VPS 到后端的网络或地址问题</td></tr><tr><td>后端通过，入口连接失败</td><td>检查入口 DNS、80/443、防火墙、规则启用状态及节点同步</td></tr><tr><td>入口证书校验失败</td><td>查看证书签发状态、域名和证书链</td></tr><tr><td>401 / 403 / 405</td><td>根据工具提示检查访问限制或用浏览器验证</td></tr><tr><td>两边通过，客户端仍异常</td><td>从客户端检查 DNS、网络与播放；服务器检查不代表公网可达</td></tr></tbody></table><p>使用出口代理、Relay 或插件后端时，脚本的直连结果不能代表规则的实际转发路径。更多说明见 <a href="./../operations/troubleshooting#只读连通性检查">排障指南</a>。</p><h2 id="跑通以后" tabindex="-1">跑通以后 <a class="header-anchor" href="#跑通以后" aria-label="Permalink to &quot;跑通以后&quot;">​</a></h2><ul><li><a href="./../guides/http-rules#给面板自身代理-https">为面板自身启用 HTTPS</a>，与业务入口分开管理。</li><li><a href="./../operations/backup-restore">备份数据</a>，保存配置与密钥。</li><li>按需增加 <a href="./../guides/l4-rules">L4 端口转发</a>、<a href="./../guides/agents">远程节点</a> 或 <a href="./../guides/relay">Relay</a>。</li></ul>`,34)])])}const F=e(p,[["render",d]]);export{y as __pageData,F as default};
